import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker, workerOptions } from "./mocks/browser";

async function startMSWWithFallbacks() {
  const tries = [
    workerOptions.serviceWorker,                            // browser.js 계산값
    { url: "/woodenpages/mockServiceWorker.js", options: { scope: "/woodenpages/" } },
    { url: "/mockServiceWorker.js", options: { scope: "/" } },
  ];
  for (const sw of tries) {
    try {
      console.log("[MSW] try", sw);
      await worker.start({ serviceWorker: sw, onUnhandledRequest: "bypass" });
      console.log("[MSW] registered at", sw.url);
      return;
    } catch (e) {
      console.warn("[MSW] failed", sw.url, e);
    }
  }
  throw new Error("MSW registration failed for all candidates");
}

async function bootstrap() {
  await startMSWWithFallbacks();
  ReactDOM.createRoot(document.getElementById("root")).render(
    <React.StrictMode><App /></React.StrictMode>
  );
}
bootstrap();
